+#pragma unroll
+  for (int i = 0; i < kPerLane; ++i) {
+    const float wf = static_cast<float>(wv[i]);
+    smem_row[lane * kPerLane + i] = DTypeTrait<T>::from(xf[i] * nf * (1.0f + wf));
