+        acc[i] = (r == 0) ? f : acc[i] + f;
+      }
+    }
+    const float inv_ratio = 1.0f / static_cast<float>(params.compress_ratio);
+#pragma unroll
+    for (int i = 0; i < kPerLane; ++i) {
+      const T m = DTypeTrait<T>::from(acc[i] * inv_ratio);
+      mf[i] = static_cast<float>(m);
+      smem_rows[warp][lane * kPerLane + i] = m;
+    }
+    __syncwarp();
