+  else if (a <= 0.75f)
+    code = 1;
+  else if (a <= 1.25f)
+    code = 2;
+  else if (a <= 1.75f)
+    code = 3;
+  else if (a <= 2.5f)
+    code = 4;
+  else if (a <= 3.5f)
+    code = 5;
+  else if (a <= 5.0f)
+    code = 6;
+  else
+    code = 7;
+  uint8_t sign = (x < 0.0f && code != 0) ? 1u : 0u;
+  return code | static_cast<uint8_t>(sign << 3);
