+
+    // Pass 2: rescale the (cached) products and store packed e4m3.
+    for (int v = tid; v < n_vec; v += kBlockThreads) {
+      const int elem_off = v * kElemPerThread;
+      uint2 fp8_pack;
+      uint16_t* fp8_arr = reinterpret_cast<uint16_t*>(&fp8_pack);
